// rolegen writes internal/foundation/authorization/roles_gen.go from the role templates of the
// master archive (05 stage, BC-D02), the single source of role templates, forbidden combinations
// and exclusive permissions. Run it with `make roles` after the archive file changes; the package's
// test fails while the generated file is stale.
package main

import (
	"bytes"
	"encoding/json"
	"flag"
	"fmt"
	"go/format"
	"os"
	"strconv"
)

// Source is the archive file this tool reads.
const Source = "docs/05_TACTICAL_DDD/06_IDP_Brant_Role_Templates_V0.1.json"

// Target is the Go file this tool writes.
const Target = "internal/foundation/authorization/roles_gen.go"

type templates struct {
	Version   string `json:"version"`
	Templates []struct {
		Code        string   `json:"code"`
		Name        string   `json:"name"`
		Duties      string   `json:"duties"`
		Permissions []string `json:"permissions"`
	} `json:"templates"`
	Forbidden []struct {
		Templates []string `json:"templates"`
		Rule      string   `json:"rule"`
	} `json:"forbiddenCombinations"`
	Exclusive []struct {
		Permission string `json:"permission"`
		Template   string `json:"template"`
		Rule       string `json:"rule"`
	} `json:"exclusivePermissions"`
}

func main() {
	src := flag.String("source", Source, "role templates JSON of the archive")
	dst := flag.String("out", Target, "generated Go file")
	flag.Parse()
	out, err := Generate(*src)
	if err == nil {
		err = os.WriteFile(*dst, out, 0o644)
	}
	if err != nil {
		fmt.Fprintln(os.Stderr, "rolegen:", err)
		os.Exit(1)
	}
}

// Generate returns the Go source for the templates in path.
func Generate(path string) ([]byte, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var t templates
	if err = json.Unmarshal(raw, &t); err != nil {
		return nil, fmt.Errorf("%s: %w", path, err)
	}
	var b bytes.Buffer
	q := strconv.Quote
	fmt.Fprintf(&b, "// Code generated by tools/rolegen from %s (version %s); DO NOT EDIT.\n\npackage authorization\n\n", Source, t.Version)
	b.WriteString("var templates = []Template{\n")
	for _, x := range t.Templates {
		fmt.Fprintf(&b, "\t{Code: %s, Name: %s, Duties: %s, Permissions: []string{", q(x.Code), q(x.Name), q(x.Duties))
		for i, p := range x.Permissions {
			if i > 0 {
				b.WriteString(", ")
			}
			b.WriteString(q(p))
		}
		b.WriteString("}},\n")
	}
	b.WriteString("}\n\nvar forbiddenCombinations = []ForbiddenCombination{\n")
	for _, f := range t.Forbidden {
		if len(f.Templates) != 2 {
			return nil, fmt.Errorf("forbidden combination %v: want two templates", f.Templates)
		}
		fmt.Fprintf(&b, "\t{A: %s, B: %s, Rule: %s},\n", q(f.Templates[0]), q(f.Templates[1]), q(f.Rule))
	}
	b.WriteString("}\n\nvar exclusivePermissions = []ExclusivePermission{\n")
	for _, e := range t.Exclusive {
		fmt.Fprintf(&b, "\t{Permission: %s, Template: %s, Rule: %s},\n", q(e.Permission), q(e.Template), q(e.Rule))
	}
	b.WriteString("}\n")
	return format.Source(b.Bytes())
}
